//! The ownership contract for exports and routines (`GeneratedFileWriter.swift`).
//! A marker identifies a generated file; only the recorded hash grants
//! permission to replace it. The hash lives in a hidden sidecar beside the file.

use std::path::{Path, PathBuf};

use crate::library::{sha256_hex, write_atomic};

pub const SIDECAR_SUFFIX: &str = ".lokalbot-generated.sha256";

#[derive(Debug, thiserror::Error)]
pub enum WriteError {
    #[error("a file LokalBot did not write has this name")]
    Collision,
    #[error("the file was edited after LokalBot wrote it")]
    Modified,
    #[error("the destination goes through a symbolic link")]
    UnsafeDestination,
    #[error(transparent)]
    Io(#[from] std::io::Error),
}

pub fn sidecar_path(path: &Path) -> PathBuf {
    let name = path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_default();
    path.with_file_name(format!(".{name}{SIDECAR_SUFFIX}"))
}

fn reject_symlink(path: &Path) -> Result<(), WriteError> {
    match std::fs::symlink_metadata(path) {
        Ok(metadata) if metadata.file_type().is_symlink() => Err(WriteError::UnsafeDestination),
        _ => Ok(()),
    }
}

/// Owner-only on Linux, where the mode exists. On Windows a file takes the
/// access of the folder it's in.
fn set_private(path: &Path) -> std::io::Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))?;
    }
    #[cfg(not(unix))]
    let _ = path;
    Ok(())
}

fn record(digest: &str, sidecar: &Path) -> std::io::Result<()> {
    let contents = format!("v1:{digest}\n");
    if std::fs::read(sidecar).ok().as_deref() != Some(contents.as_bytes()) {
        write_atomic(sidecar, contents.as_bytes())?;
    }
    set_private(sidecar)
}

/// Writes `data` unless the person owns what is there. Returns false when
/// identical bytes were already present: legacy files can be adopted only then,
/// without replacing their content.
pub fn write(data: &[u8], path: &Path, marker: &str) -> Result<bool, WriteError> {
    let sidecar = sidecar_path(path);
    reject_symlink(path)?;
    reject_symlink(&sidecar)?;
    let new_digest = sha256_hex(data);
    if path.exists() {
        let existing = std::fs::read(path)?;
        if !String::from_utf8_lossy(&existing).contains(marker) {
            return Err(WriteError::Collision);
        }
        if existing == data {
            set_private(path)?;
            record(&new_digest, &sidecar)?;
            return Ok(false);
        }
        let recorded = std::fs::read_to_string(&sidecar).ok();
        let expected = format!("v1:{}", sha256_hex(&existing));
        if recorded.as_deref().map(str::trim) != Some(expected.as_str()) {
            return Err(WriteError::Modified);
        }
        if std::fs::read(path)? != existing {
            return Err(WriteError::Modified);
        }
    }
    write_atomic(path, data)?;
    set_private(path)?;
    record(&new_digest, &sidecar)?;
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;

    const MARKER: &str = "<!-- Generated by LokalBot test. -->";

    fn body(text: &str) -> Vec<u8> {
        format!("{MARKER}\n{text}\n").into_bytes()
    }

    #[test]
    fn writes_refreshes_and_records_the_hash_in_the_macs_format() {
        let dir = tempfile::tempdir().unwrap();
        let note = dir.path().join("a note.md");
        assert!(write(&body("one"), &note, MARKER).unwrap());
        let sidecar = dir.path().join(".a note.md.lokalbot-generated.sha256");
        assert_eq!(
            std::fs::read_to_string(&sidecar).unwrap(),
            format!("v1:{}\n", sha256_hex(&body("one")))
        );
        // Identical bytes: nothing rewritten.
        assert!(!write(&body("one"), &note, MARKER).unwrap());
        // Still what LokalBot wrote: replaced.
        assert!(write(&body("two"), &note, MARKER).unwrap());
        assert_eq!(std::fs::read(&note).unwrap(), body("two"));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            let mode = |path: &Path| std::fs::metadata(path).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode(&note), 0o600);
            assert_eq!(mode(&sidecar), 0o600);
        }
    }

    #[test]
    fn a_file_the_person_owns_is_never_replaced() {
        let dir = tempfile::tempdir().unwrap();
        let mine = dir.path().join("mine.md");
        std::fs::write(&mine, "my own notes").unwrap();
        assert!(matches!(
            write(&body("x"), &mine, MARKER),
            Err(WriteError::Collision)
        ));
        assert_eq!(std::fs::read_to_string(&mine).unwrap(), "my own notes");

        // Generated, then edited: the hash no longer matches.
        let edited = dir.path().join("edited.md");
        write(&body("one"), &edited, MARKER).unwrap();
        let mut changed = body("one");
        changed.extend_from_slice(b"my addition\n");
        std::fs::write(&edited, &changed).unwrap();
        assert!(matches!(
            write(&body("two"), &edited, MARKER),
            Err(WriteError::Modified)
        ));
        assert_eq!(std::fs::read(&edited).unwrap(), changed);

        // Marker but no sidecar: only identical bytes may be adopted.
        let legacy = dir.path().join("legacy.md");
        std::fs::write(&legacy, body("old")).unwrap();
        assert!(matches!(
            write(&body("new"), &legacy, MARKER),
            Err(WriteError::Modified)
        ));
        assert!(!write(&body("old"), &legacy, MARKER).unwrap());
        assert!(sidecar_path(&legacy).exists());
    }

    #[cfg(unix)]
    #[test]
    fn symlinks_are_refused() {
        let dir = tempfile::tempdir().unwrap();
        let target = dir.path().join("target.md");
        std::fs::write(&target, "elsewhere").unwrap();
        let link = dir.path().join("link.md");
        std::os::unix::fs::symlink(&target, &link).unwrap();
        assert!(matches!(
            write(&body("x"), &link, MARKER),
            Err(WriteError::UnsafeDestination)
        ));
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "elsewhere");

        let note = dir.path().join("note.md");
        std::os::unix::fs::symlink(&target, sidecar_path(&note)).unwrap();
        assert!(matches!(
            write(&body("x"), &note, MARKER),
            Err(WriteError::UnsafeDestination)
        ));
    }
}
